using System.Drawing;using System.Windows.Forms;
namespace LSE.AutoCADElectrical.CatalogTools;
public sealed class CatalogAdminForm:Form{
 readonly AppSettings s=SettingsService.Load();readonly ComboBox table=new(){DropDownStyle=ComboBoxStyle.DropDownList,Width=220};readonly TextBox cat=new(),mfg=new(),desc=new(),type=new(),rating=new(),user1=new(),user2=new(),user3=new(),textvalue=new(),wdblk=new();readonly Label result=new(){AutoSize=true};
 public CatalogAdminForm(){Text="LSE Electrical Catalog Administrator";StartPosition=FormStartPosition.CenterParent;Size=new Size(850,650);Build();Shown+=(_,_)=>{try{table.DataSource=new AccessCatalogService(s.CatalogPath).GetTables();}catch(Exception ex){MessageBox.Show(ex.Message);}};}
 void Build(){var p=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=3,Padding=new Padding(14),AutoScroll=true};p.ColumnStyles.Add(new(SizeType.Absolute,170));p.ColumnStyles.Add(new(SizeType.Percent,100));p.ColumnStyles.Add(new(SizeType.Absolute,130));int r=0;Add(p,"Catalog family/table",table,r++);Add(p,"Manufacturer",mfg,r++);Add(p,"Catalog number",cat,r++);Add(p,"Description",desc,r++);Add(p,"Type",type,r++);Add(p,"Rating",rating,r++);Add(p,"LSE Part Number (USER1)",user1,r++);Add(p,"USER2",user2,r++);Add(p,"USER3",user3,r++);Add(p,"TEXTVALUE",textvalue,r++);Add(p,"WDBLKNAM",wdblk,r++);var add=new Button{Text="Add to catalog",Dock=DockStyle.Fill,Height=38};add.Click+=(_,_)=>AddRecord();var standards=new Button{Text="Manage standards",Dock=DockStyle.Fill};standards.Click+=(_,_)=>MessageBox.Show("Company standards are stored separately at:\r\n"+s.CompanyStandardsPath+"\r\n\r\nUse the browser to identify a record, then add its record key to the standards file. A grid editor is the next admin-only refinement.","Company Standards");p.Controls.Add(result,0,r);p.SetColumnSpan(result,1);p.Controls.Add(standards,1,r);p.Controls.Add(add,2,r);Controls.Add(p);}
 static void Add(TableLayoutPanel p,string label,Control c,int r){p.RowStyles.Add(new(SizeType.Absolute,42));p.Controls.Add(new Label{Text=label,AutoSize=true,Anchor=AnchorStyles.Left},0,r);c.Dock=DockStyle.Fill;p.Controls.Add(c,1,r);p.SetColumnSpan(c,2);}
 void AddRecord(){try{var q=new CatalogAddRequest{TableName=Convert.ToString(table.SelectedItem)??"",Catalog=cat.Text.Trim(),Manufacturer=mfg.Text.Trim(),Description=desc.Text.Trim(),Type=type.Text.Trim(),Rating=rating.Text.Trim(),User1=user1.Text.Trim(),User2=user2.Text.Trim(),User3=user3.Text.Trim(),TextValue=textvalue.Text.Trim(),WdBlkNam=wdblk.Text.Trim()};if(q.TableName.Length==0||q.Catalog.Length==0||q.Manufacturer.Length==0||q.User1.Length==0)throw new InvalidOperationException("Table, Manufacturer, Catalog number, and LSE Part Number (USER1) are required.");var report=CatalogTransactionService.Execute(s,q);result.Text=report;MessageBox.Show(report,"Catalog transaction");}catch(Exception ex){MessageBox.Show(ex.Message,"Catalog transaction failed",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
}
